import{_ as a,o as t,c as l,a5 as o}from"./chunks/framework.DOB-AMqW.js";const f=JSON.parse('{"title":"Who Called Data Deletion","description":"Official data-deletion instructions for Who Called.","frontmatter":{"title":"Who Called Data Deletion","description":"Official data-deletion instructions for Who Called.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/who-called.md","filePath":"data-deletion/who-called.md"}'),d={name:"data-deletion/who-called.md"};function s(r,e,n,i,c,h){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="delete-who-called-data" tabindex="-1">Delete Who Called Data <a class="header-anchor" href="#delete-who-called-data" aria-label="Permalink to &quot;Delete Who Called Data&quot;">​</a></h1><p>Who Called has no online account or developer-operated cloud database. Its app records are stored encrypted on your device.</p><h2 id="delete-contacts" tabindex="-1">Delete contacts <a class="header-anchor" href="#delete-contacts" aria-label="Permalink to &quot;Delete contacts&quot;">​</a></h2><p>Move contacts to <strong>Trash</strong>. Restore them within 30 days or permanently delete selected contacts from Trash. You can also empty Trash. Contacts still in Trash are automatically removed after 30 days when the app loads.</p><h2 id="delete-other-records" tabindex="-1">Delete other records <a class="header-anchor" href="#delete-other-records" aria-label="Permalink to &quot;Delete other records&quot;">​</a></h2><p>Delete saved messages and tagged numbers from their corresponding screens.</p><h2 id="delete-all-local-data" tabindex="-1">Delete all local data <a class="header-anchor" href="#delete-all-local-data" aria-label="Permalink to &quot;Delete all local data&quot;">​</a></h2><p>Clear Who Called storage in Android system settings or uninstall the app. In a browser, clear the site&#39;s IndexedDB/site data.</p><h2 id="delete-files-outside-the-app" tabindex="-1">Delete files outside the app <a class="header-anchor" href="#delete-files-outside-the-app" aria-label="Permalink to &quot;Delete files outside the app&quot;">​</a></h2><p>Clearing app data does not remove <code>.contactvault</code> backups, CSV exports, or vCard files saved or shared outside Who Called. Delete those copies separately from every destination.</p><p>The optional call-history list is not stored by Who Called. Android manages the device call log separately. Because the developer holds no account data, emailing support cannot delete records stored on your device.</p>',11)])])}const u=a(d,[["render",s]]);export{f as __pageData,u as default};
